import io.netty.channel.Channel;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;
import org.traccar.Protocol;
import org.traccar.model.Position;
import java.net.SocketAddress;

public class WatchProtocolDecoderTest {

    @Test
    public void WatchProtocolDecoderConstructorTest() {
        Protocol protocol = new Protocol("test");

        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        Assert.assertNotNull(decoder);
    }

    @Test
    public void getHasIndexTest() {
        Protocol protocol = new Protocol("test");
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        boolean result = decoder.getHasIndex();

        Assert.assertFalse(result);
    }

    @Test
    public void getManufacturerTest() {
        Protocol protocol = new Protocol("test");
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        String manufacturer = decoder.getManufacturer();

        Assert.assertNull(manufacturer);
    }

    @Test
    public void decodeWithNullMessageTest() throws Exception {
        Protocol protocol = new Protocol("test");
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        Channel channel = Mockito.mock(Channel.class);
        SocketAddress address = Mockito.mock(SocketAddress.class);

        Position result = (Position) decoder.decode(channel, address, null);

        Assert.assertNull(result);
    }

    @Test
    public void decodeWithUnknownMessageTest() throws Exception {
        Protocol protocol = new Protocol("test");
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        Channel channel = Mockito.mock(Channel.class);
        SocketAddress address = Mockito.mock(SocketAddress.class);

        Position result = (Position) decoder.decode(channel, address, "unknown");

        Assert.assertNull(result);
    }

